mapper.sql:

WHERE c.user_id=#{userId} AND c.habit_id=#{habitId}

AND c.business_date>=#{q.dateFrom}

AND c.business_date<=#{q.dateTo}

AND (c.cancelled_at IS NOT NULL)=#{q.cancelled}

mapper.select:

SELECT c.id::text,c.habit_id::text,c.revision_id::text,r.name AS name_snapshot,r.category_id::text AS category_id,

    c.business_date,c.time_zone,c.checked_at,c.cancelled_at,c.version FROM habit_checkin c JOIN habit_revision r ON r.id=c.revision_id AND r.user_id=c.user_id AND r.habit_id=c.habit_id

WHERE c.user_id=#{userId} AND c.id=#{id}


SELECT c.id::text,c.habit_id::text,c.revision_id::text,r.name AS name_snapshot,r.category_id::text AS category_id,

    c.business_date,c.time_zone,c.checked_at,c.cancelled_at,c.version FROM habit_checkin c JOIN habit_revision r ON r.id=c.revision_id AND r.user_id=c.user_id AND r.habit_id=c.habit_id

 ORDER BY c.checked_at DESC,c.id DESC LIMIT #{q.size} OFFSET #{q.offset}
